interface DisclosureRecord {
  id: number;
  userId: number;
  userName: string | null;
  planSlug: string;
  billingInterval: string;
  priceAtAcceptance: string;
  payorFirstName: string;
  payorLastName: string;
  payorBusinessEntity: string | null;
  payorAddress: string;
  payorCity: string;
  payorState: string;
  payorZip: string;
  payorPhone: string;
  payorEmail: string | null;
  ipAddress: string | null;
  userAgent: string | null;
  pinVerifiedAt: string | null;
  signatureText: string;
  signatureHash: string;
  disclosureVersion: string;
  governingLaw: string;
  agreedAt: string;
  createdAt: string;
}

export default function LegalPaymentFolder() {
  const { user } = useAuth();
  const [searchTerm, setSearchTerm] = useState("");
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [activeTab, setActiveTab] = useState("disclosures");
  const [filterPlan, setFilterPlan] = useState("ALL");
  const [filterInterval, setFilterInterval] = useState("ALL");
  const [filterVerified, setFilterVerified] = useState("ALL");
  const [selectedRecords, setSelectedRecords] = useState<number[]>([]);

  const [showFilters, setShowFilters] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [sortField, setSortField] = useState<string>("agreedAt");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");

  const disclosuresQuery = trpc.paymentCompliance.listDisclosures.useQuery(
    { page, pageSize, search: searchTerm || undefined } as any,
    { staleTime: 15_000 }
  );
  const complianceAlertsQuery = trpc.complianceAlerts.getAlerts.useQuery(undefined, { staleTime: 60000 });
  const paymentStatsQuery = trpc.billing.getStats.useQuery(undefined, { staleTime: 60000 });
  const auditLogsQuery = trpc.complianceAudit.getLogs.useQuery(undefined, { staleTime: 60000 });
  const riskScoringQuery = trpc.riskScoring.scores.useQuery(undefined, { staleTime: 60000 });

  const records = (disclosuresQuery.data?.rows ?? []) as unknown as DisclosureRecord[];
  const total = disclosuresQuery.data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  const toggleExpand = (id: number) => setExpandedId(expandedId === id ? null : id);
  const toggleSelect = (id: number) => {
    setSelectedRecords(prev => prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]);
  };
  const toggleSelectAll = () => {
    if (selectedRecords.length === records.length) setSelectedRecords([]);
    else setSelectedRecords(records.map((r) => r.id));
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return "N/A";
    return new Date(dateStr).toLocaleDateString("en-US", {
      year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit"
    });
  };

  const handleSort = (field: string) => {
    if (sortField === field) {
      setSortDirection(prev => prev === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("desc");
    }
  };

  const exportCsv = () => {
    if (!records.length) return;
    const headers = [
      "ID", "User", "Plan", "Interval", "Price", "Payor Name", "Business Entity",
      "Address", "City", "State", "Zip", "Phone", "Email", "IP Address",
      "PIN Verified", "Signature", "Signature Hash", "Version", "Governing Law",
      "Agreed At", "Created At"
    ];
    const rows = records.map((r) => [
      r.id, r.userName ?? "", r.planSlug, r.billingInterval, r.priceAtAcceptance,
      `${r.payorFirstName} ${r.payorLastName}`, r.payorBusinessEntity ?? "",
      r.payorAddress, r.payorCity, r.payorState, r.payorZip, r.payorPhone,
      r.payorEmail ?? "", r.ipAddress ?? "", r.pinVerifiedAt ?? "",
      r.signatureText, r.signatureHash, r.disclosureVersion, r.governingLaw,
      r.agreedAt, r.createdAt
    ]);
    const csv = [headers, ...rows].map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `legal-payment-disclosures-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

